        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 5);

            var briefEl = document.getElementById('briefingPanel');
            if (briefEl) briefEl.innerHTML = this._getBriefingHTML(idx);

            var decEl = document.getElementById('decisionsPanel');
            if (decEl) decEl.innerHTML = this._getDecisionsHTML(idx);

            var budgetBar = document.getElementById('budgetBar');
            if (budgetBar) budgetBar.style.display = (idx === 0) ? 'block' : 'none';

            if (idx === 0) this._setupBudgetListeners();
        }

        _setupBudgetListeners() {
            var self = this;
            var caps = self.BUDGET_CAP;
            var ints = self.INTERVENTIONS;
            for (var i = 0; i < ints.length; i++) {
                var cb = document.getElementById(ints[i].id);
                if (cb) {
                    cb.addEventListener('change', function() {
                        var total = 0;
                        for (var j = 0; j < ints.length; j++) {
                            var el = document.getElementById(ints[j].id);
                            if (el && el.checked) total += ints[j].cost;
                        }
                        var usedEl = document.getElementById('budgetUsed');
                        if (usedEl) {
                            usedEl.textContent = '$' + total + 'K';
                            usedEl.className = total > caps ? 'wlp-over-budget' : '';
                        }
                    });
                }
            }
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation.state.currentPeriod || 1);

            if (round === 1) {
                var funded = [];
                var totalCost = 0;
                for (var i = 0; i < this.INTERVENTIONS.length; i++) {
                    var cb = document.getElementById(this.INTERVENTIONS[i].id);
                    if (cb && cb.checked) {
                        funded.push(this.INTERVENTIONS[i].id);
                        totalCost += this.INTERVENTIONS[i].cost;
                    }
                }
                if (funded.length === 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_no_selection'), 'warning');
                    return false;
                }
                if (totalCost > this.BUDGET_CAP) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_over_budget'), 'warning');
                    return false;
                }
                decisions.funded = funded;
                decisions.totalCost = totalCost;
                return true;
            }

            if (round === 2) {
                var s = document.getElementById('r2scope');
                var d = document.getElementById('r2disc');
                var c = document.getElementById('r2comm');
                if (!s || !s.value || !d || !d.value || !c || !c.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
                }
                decisions.r2scope = s.value;
                decisions.r2disc = d.value;
                decisions.r2comm = c.value;
                return true;
            }

            if (round === 3) {
                var su = document.getElementById('r3succ');
                var sp = document.getElementById('r3spons');
                var pr = document.getElementById('r3proc');
                if (!su || !su.value || !sp || !sp.value || !pr || !pr.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
                }
                decisions.r3succ = su.value;
                decisions.r3spons = sp.value;
                decisions.r3proc = pr.value;
                return true;
            }

            if (round === 4) {
                var p = document.getElementById('r4par');
                var f = document.getElementById('r4flex');
                var co = document.getElementById('r4comp');
                var pm = document.getElementById('r4prom');
                if (!p || !p.value || !f || !f.value || !co || !co.value || !pm || !pm.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
                }
                decisions.r4par = p.value;
                decisions.r4flex = f.value;
                decisions.r4comp = co.value;
                decisions.r4prom = pm.value;
                return true;
            }

            if (round === 5) {
                var re = document.getElementById('r5res');
                var me = document.getElementById('r5meas');
                var cm = document.getElementById('r5comp');
                if (!re || !re.value || !me || !me.value || !cm || !cm.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
                }
                decisions.r5res = re.value;
                decisions.r5meas = me.value;
                decisions.r5comp = cm.value;
                return true;
            }

            if (round === 6) {
                var fr = document.getElementById('r6frame');
                var nx = document.getElementById('r6next');
                if (!fr || !fr.value || !nx || !nx.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
                }
                decisions.r6frame = fr.value;
                decisions.r6next = nx.value;
                return true;
            }

            return true;
        }

        _applyScores(ds, scoreObj) {
            ds.pei = Math.min(100, Math.max(0, ds.pei + (scoreObj.pei || 0)));
            ds.ocs = Math.min(100, Math.max(0, ds.ocs + (scoreObj.ocs || 0)));
            ds.tri = Math.min(100, Math.max(0, ds.tri + (scoreObj.tri || 0)));
            ds.rcs = Math.min(100, Math.max(0, ds.rcs + (scoreObj.rcs || 0)));
            ds.bci = Math.min(100, Math.max(0, ds.bci + (scoreObj.bci || 0)));
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var peiDelta = 0, ocsDelta = 0, triDelta = 0, rcsDelta = 0, bciDelta = 0;

            if (round === 1) {
                var funded = d.funded || [];
                for (var i = 0; i < this.INTERVENTIONS.length; i++) {
                    if (funded.indexOf(this.INTERVENTIONS[i].id) !== -1) {
                        peiDelta += this.INTERVENTIONS[i].pei;
                        ocsDelta += this.INTERVENTIONS[i].ocs;
                        triDelta += this.INTERVENTIONS[i].tri;
                        rcsDelta += this.INTERVENTIONS[i].rcs;
                        bciDelta += this.INTERVENTIONS[i].bci;
                    }
                }
            }

            if (round === 2) {
                var keys2 = [d.r2scope, d.r2disc, d.r2comm];
                for (var k = 0; k < keys2.length; k++) {
                    var sc = this.R2_SCORES[keys2[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 3) {
                var keys3 = [d.r3succ, d.r3spons, d.r3proc];
                for (var k = 0; k < keys3.length; k++) {
                    var sc = this.R3_SCORES[keys3[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 4) {
                var keys4 = [d.r4par, d.r4flex, d.r4comp, d.r4prom];
                for (var k = 0; k < keys4.length; k++) {
                    var sc = this.R4_SCORES[keys4[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 5) {
                var keys5 = [d.r5res, d.r5meas, d.r5comp];
                for (var k = 0; k < keys5.length; k++) {
                    var sc = this.R5_SCORES[keys5[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 6) {
                var keys6 = [d.r6frame, d.r6next];
                for (var k = 0; k < keys6.length; k++) {
                    var sc = this.R6_SCORES[keys6[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            ds.pei = Math.min(100, Math.max(0, ds.pei + peiDelta));
            ds.ocs = Math.min(100, Math.max(0, ds.ocs + ocsDelta));
            ds.tri = Math.min(100, Math.max(0, ds.tri + triDelta));
            ds.rcs = Math.min(100, Math.max(0, ds.rcs + rcsDelta));
            ds.bci = Math.min(100, Math.max(0, ds.bci + bciDelta));

            var overall = Math.round(ds.pei * 0.25 + ds.ocs * 0.20 + ds.tri * 0.20 + ds.rcs * 0.20 + ds.bci * 0.15);

            ds.peiHistory.push(ds.pei);
            ds.ocsHistory.push(ds.ocs);
            ds.triHistory.push(ds.tri);
            ds.rcsHistory.push(ds.rcs);
            ds.bciHistory.push(ds.bci);
            ds.overallHistory.push(overall);

            // score: overall is already a 0-100 weighted composite of pei/ocs/tri/rcs/bci
            // (weights sum to 1), the same figure getPerformanceSummary uses for its
            // verdict bands, so reuse it directly here, clamped
            var overallScore = Math.max(0, Math.min(100, Math.round(overall)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            var period = round;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: round,
                peiDelta: peiDelta,
                ocsDelta: ocsDelta,
                triDelta: triDelta,
                rcsDelta: rcsDelta,
                bciDelta: bciDelta,
                pei: ds.pei,
                ocs: ds.ocs,
                tri: ds.tri,
                rcs: ds.rcs,
                bci: ds.bci,
                overall: overall
            };
        }

