        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var overall = r.overall || 0;

            var performance = window.mySimulation.t('perf_developing');
            if (overall >= 75) performance = window.mySimulation.t('perf_excellent');
            else if (overall >= 60) performance = window.mySimulation.t('perf_proficient');
            else if (overall >= 45) performance = window.mySimulation.t('perf_competent');

            var insights = [];
            if (r.pei >= 55) insights.push(window.mySimulation.t('insight_pei_strong'));
            if (r.pei < 40) insights.push(window.mySimulation.t('insight_pei_weak'));
            if (r.ocs >= 70) insights.push(window.mySimulation.t('insight_ocs_strong'));
            if (r.ocs < 55) insights.push(window.mySimulation.t('insight_ocs_weak'));
            if (r.rcs >= 75) insights.push(window.mySimulation.t('insight_rcs_strong'));
            if (r.bci >= 65) insights.push(window.mySimulation.t('insight_bci_strong'));
            if (r.tri < 50) insights.push(window.mySimulation.t('insight_tri_weak'));

            return {
                overall: overall,
                pei: r.pei,
                ocs: r.ocs,
                tri: r.tri,
                rcs: r.rcs,
                bci: r.bci,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var round = results.period;
            if (round === 1 && results.peiDelta < 5) return window.mySimulation.t('hint_r1_low_pei');
            if (round === 2 && results.rcsDelta < 8) return window.mySimulation.t('hint_r2_low_rcs');
            if (round === 3 && results.peiDelta < 5) return window.mySimulation.t('hint_r3_low_pei');
            if (round === 4 && results.triDelta < 8) return window.mySimulation.t('hint_r4_low_tri');
            if (round === 5 && results.ocsDelta < 5) return window.mySimulation.t('hint_r5_low_ocs');
            if (round === 6 && results.bciDelta < 4) return window.mySimulation.t('hint_r6_low_bci');
            return null;
        }

